{
  "status": "SUPPORTED",
  "task_summary": "Find fastening parts and tool, perform fastening, leave tool on bench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "An implement used to apply force to secure components.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "pliers", "drill"],
        "required_properties": ["capable of manipulating fasteners"]
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "A part that physically connects or secures other items.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screw", "bolt", "nut", "clip", "pin"],
        "required_properties": ["compatible with target location"]
      },
      {
        "id": "target_location",
        "entity_kind": "REGION",
        "function": "The specific area on the workbench where fastening occurs.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["workbench surface", "assembly point"],
        "required_properties": ["flat or stable enough to hold items"]
      },
      {
        "id": "storage_container",
        "entity_kind": "OBJECT",
        "function": "A closed or enclosed structure potentially holding spare parts.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["cabinet", "drawer", "toolbox"],
        "required_properties": ["enclosed space"]
      }
    ],
    "functional_relations": [
      {
        "id": "fastening_action",
        "relation": "The fastening tool is used to attach the fastening component to the target location.",
        "participant_roles": ["fastening_tool", "fastening_component", "target_location"]
      ,
        "required": true
      },
      {
        "id": "final_placement",
        "relation": "After the task, the fastening tool rests on the target location.",
        "participant_roles": ["fastening_tool", "target_location"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_components",
        "operation": "Inspect storage containers and visible surfaces to identify the tool and component.",
        "participant_roles": ["fastening_tool", "fastening_component", "storage_container"],
        "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "Secure the fastening component to the target location using the fastening tool.",
        "participant_roles": ["fastening_tool", "fastening_component", "target_location"],
        "operation_count": 1
      },
      {
        "id": "return_equipment",
        "operation": "Place the fastening tool onto the target location.",
        "participant_roles": ["fastening_tool", "target_location"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_tool": [
        {
          "label": "Yellow handled tool on tray",
          "visual_description": "A tool with a yellow handle and metal shaft visible on the black tray."
        }
      ],
      "fastening_component": [
        {
          "label": "Small metallic object on tray",
          "visual_description": "A small blocky object next to the tool on the black tray."
        }
      ],
      "target_location": [
        {
          "label": "Black tray surface",
          "visual_description": "The black rectangular tray sitting on the wooden table."
        }
      ],
      "storage_container": [
        {
          "label": "Blue cabinet behind table",
          "visual_description": "A tall blue cabinet standing against the wall behind the table."
        },
        {
          "label": "Table drawers",
          "visual_description": "Two blue drawers located underneath the table surface."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "Blue Cabinet",
        "visual_description": "A closed blue cabinet with a handle, positioned behind the workbench.",
        "reason": "Likely contains spare parts or tools hidden inside."
      },
      {
        "id": "under_table_drawers",
        "label": "Under Table Drawers",
        "visual_description": "Closed blue drawers underneath the table legs.",
        "reason": "Likely contains tools or components stored underneath."
      },
      {
        "id": "tray_on_table",
        "label": "Tray on Table",
        "visual_description": "A black tray with items on top of the wooden table.",
        "reason": "Visible candidates for the fastening tool and component are present here."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "under_table_drawers",
      "tray_on_table"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
